def primes_up_to(n):
    if n < 2:
        return []
    sieve = bytearray(b"\x01") * (n + 1)
    sieve[0:2] = b"\x00\x00"
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            start = i * i
            sieve[start:n + 1:i] = b"\x00" * (((n - start) // i) + 1)
    return [i for i, is_prime in enumerate(sieve) if is_prime]
```

