def parse_kv(text: str) -> dict:
    """
    Parse a string of key=value pairs separated by semicolons into a dict.

    Example:
        parse_kv("a=1;b=2") -> {"a": "1", "b": "2"}

    An empty input string returns an empty dict.
    """
    if not text:
        return {}

    result = {}
    for pair in text.split(';'):
        if not pair:
            continue
        if '=' not in pair:
            # Skip malformed entries without an '='
            continue
        key, value = pair.split('=', 1)
        result[key] = value
    return result
