    """
    Counts the occurrences of each lowercased whitespace-separated word in the given text.

    Args:
        text (str): The input string to analyze.

    Returns:
        dict: A dictionary where keys are lowercased words and values are their counts.
    """
    if not text:
        return {}

    # Split the text by any whitespace (spaces, tabs, newlines) and convert to lowercase
    words = text.lower().split()

    # Initialize an empty dictionary to store counts
    counts = {}

    # Iterate over each word and update the count
    for word in words:
        if word in counts:
            counts[word] += 1
        else:
            counts[word] = 1

    return counts
