def gcd_list(numbers):
    """
    Returns the greatest common divisor of a non-empty list of positive integers.
    """
    def compute_gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    result = numbers[0]
    for num in numbers[1:]:
        result = compute_gcd(result, num)
        if result == 1:
            break
    return result
