    """
    Parse a semicolon-separated list of key=value pairs into a dictionary.

    Args:
        text: Input string, e.g. "a=1;b=2". An empty string returns {}.

    Returns:
        A dictionary mapping each key to its corresponding value as strings.
    """
    if not text:
        return {}

    result: dict[str, str] = {}
    for pair in text.split(';'):
        if not pair:
            continue  # skip empty segments (e.g., trailing ';')
        if '=' not in pair:
            raise ValueError(f"Invalid pair without '=': {pair!r}")
        key, value = pair.split('=', 1)
        result[key] = value
    return result
