def parse_kv(text):
    """
    Parses a string of key-value pairs separated by semicolons into a dictionary.
    Handles empty strings and missing values gracefully.
    """
    if not text:
        return {}

    result = {}
    # Split the text by semicolons
    pairs = text.split(';')

    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
            result[key] = value
        else:
            # If there is no '=', the key is stored with an empty string value
            result[pair] = ''

    return result
