def is_balanced(text: str) -> bool:
    """
    Return True if all parentheses, brackets, and braces in `text` are properly balanced.
    Supports: (), [], {}
    Any other characters are ignored.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    stack = []

    for ch in text:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()

    return not stack
