def is_balanced(text):
    """
    Checks if the brackets (), [], and {} in the given string are balanced.
    """
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}

    for char in text:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map:
            if not stack or stack[-1] != bracket_map[char]:
                return False
            stack.pop()

    return not stack
```

