def word_count(text):
    """
    Returns a dictionary counting each lowercased whitespace-separated word in the input text.
    """
    if not text:
        return {}

    # Split the text by any whitespace (spaces, tabs, newlines) and convert to lowercase
    words = text.lower().split()

    # Count occurrences of each word
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1

    return counts
